var doc = Document;
// Goal: a review note on the lowest level's floor plan, and the notes in that view read back.

// 1. The view to annotate and a text type. Text notes are view-specific; the type controls font
//    and size (the first TextNoteType is the template's default).
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) { if (level == null || l.Elevation < level.Elevation) level = l; }
Autodesk.Revit.DB.ViewPlan view = null;
foreach (Autodesk.Revit.DB.ViewPlan v in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.ViewPlan))) {
  if (!v.IsTemplate && v.GenLevel != null && v.GenLevel.Id == level.Id) { view = v; break; }
}
Autodesk.Revit.DB.ElementId typeId = null;
foreach (Autodesk.Revit.DB.TextNoteType t in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.TextNoteType))) { typeId = t.Id; break; }

return Connector.WithTransaction(doc, () => {
  // 2. Create. The position is in the view's model coordinates (feet); this overload makes an
  //    unwrapped single line. TextNote.Create(doc, viewId, position, width, text, options) wraps at a width.
  string text = "REVIEW: confirm door swing at corridor";
  var note = Autodesk.Revit.DB.TextNote.Create(doc, view.Id, new Autodesk.Revit.DB.XYZ(10, 10, 0), text, typeId);
  doc.Regenerate();

  // 3. Read back. TextNote.Text returns the text with a trailing "\r" appended (undocumented);
  //    trim it before comparing or reporting.
  var notesInView = new System.Collections.Generic.List<object>();
  foreach (Autodesk.Revit.DB.TextNote n in new Autodesk.Revit.DB.FilteredElementCollector(doc).OwnedByView(view.Id).OfClass(typeof(Autodesk.Revit.DB.TextNote))) {
    notesInView.Add(new { id = n.Id.Value, text = n.Text.TrimEnd('\r'), rawLength = n.Text.Length });
  }

  // 4. Verify: the note exists in the view and its trimmed text equals what was written.
  return new { noteId = note.Id.Value, viewName = view.Name, textMatches = note.Text.TrimEnd('\r') == text, rawEndsWithCR = note.Text.EndsWith("\r"), notesInView };
});
